  ctx=[arith("El techo de una casa tiene forma de triángulo con ángulos de 40° y 70° en la base. ¿Cuánto mide el ángulo de la punta?", "180-(40+70)", "Se resta de 180° la suma de los dos ángulos de la base.", "°")],
